#!/usr/bin/env bash
# test_gate_pl_big_integer_multiplication_is_exact_at_every_size.sh -- BIG-INTEGER MULTIPLICATION IS EXACT AT EVERY SIZE AND KARATSUBA-FAST PAST 32 LIMBS (bignum.c lmul).
# hq_prolog 2026-09-25, CEO-1270; the cure is bignum.c big_umul: schoolbook O(n^2) at -O0 took 5.5-9 s for 7^823543 (Logtalk unbounded's four
# 7^7^7 cases timed out at the grader's 10 s), now Karatsuba past 32 limbs with ONE scratch buffer of 4(an+bn)+256 limbs handed down the recursion
# (a first cut allocated per node and, since the collector never runs inside a runtime call, exhausted the 128 MB heap at 2.2 M bits). 0.7 s.
# THE ARM: 12 exact products and negated squares across the 32-limb threshold (3^E, E = 31..2500) printed in full, then two algebraic identities
# per size up to 960 K bits (A*B - A*(B-1) = A and (A+B)^2 = A^2 + 2AB + B^2, no division, no oracle needed) -- 22 lines byte-equal to swipl's GMP.
# FAIL-ONCE: schoolbook was already exact, so origin passes; the proof is a PLANTED fault in the landing -- lsub_from's borrow dropped -- which
# turns the exact lines and the identities red (measured; see the commit).
set -u
GATE_NAME=test_gate_pl_big_integer_multiplication_is_exact_at_every_size
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SCRIP="${SCRIP_BIN:-$HERE/../../SCRIP/scrip}"
RT="${RT_DIR:-$(dirname "$SCRIP")/out}"
refuse() { echo "⛔ REFUSED(2) [$GATE_NAME]: $*" >&2; exit 2; }
[ -x "$SCRIP" ] || refuse "no scrip binary at $SCRIP -- run make first"
[ -n "${SCRIP_BIN:-}" ] || "$HERE/util_require_fresh.sh" --gate "$GATE_NAME" "$SCRIP" "$RT/libscrip_rt.so" || exit 2
TMPD="$(mktemp -d)"; trap 'rm -rf "$TMPD"' EXIT
cat > "$TMPD/w.pl" <<'EOP'
chk(N, A, B) :- P is A * B, Q is A * (B - 1), ( P - Q =:= A -> T1 = ok ; T1 = bad ), S is (A + B) * (A + B), R is A*A + 2*A*B + B*B, ( S =:= R -> T2 = ok ; T2 = bad ), write(N-T1-T2), nl.
main :- forall(member(E, [31, 64, 65, 300, 1023, 2500]), ( A is 3^E + 12345, B is 7^(E // 2 + 3) - 1, C is A * B, write(C), nl, D is -(A) * A, write(D), nl )),
        forall(member(K, [40, 200, 1500, 9000, 30000]), ( A is 3^(K*20) + 7, B is 5^(K*13) - 11, chk(K, A, B), C is 2^(K*32) - 1, chk(ones(K), C, C) )).
:- initialization(main).
EOP
want='1005827757596410841793490458816
-381520424492196187783052949264
1300743614456981499317246615413290822230520470724180211981692
-11790184577738583171520872946190172188700344838478135275843876
3902230843370944497951739836886838954652297952426242451437096
-106111661199647248543687856007045628560170304069089452177315344
273134486247639779105324306399264340330341909375865925320401889282379585178901266841563216960535987229428369628952454977967912021500517447635860865121860205924267606304772820036333662303510516843275590845086584086236743001673178805796055905094680752775656497926229107716476
-18739277038847939886754019920358123424308469030992781557966909983211910963157763678726120154469030856807730587971859910379069087693119051088519416835327182086610783229931790066468885762988189463324545358128224306145593510627623447126560829811593944609242287931526824209677252554092095716

-

-
40-ok-ok
ones(40)-ok-ok
200-ok-ok
ones(200)-ok-ok
1500-ok-ok
ones(1500)-ok-ok
9000-ok-ok
ones(9000)-ok-ok
30000-ok-ok
ones(30000)-ok-ok'
red=0
for mode in m3 m4; do
    if [ "$mode" = m3 ]; then got="$(cd "$TMPD" && timeout -k 5 20 "$SCRIP" w.pl </dev/null 2>"$TMPD/err")"; rc=$?
    else
        timeout -k 5 60 "$SCRIP" --compile -o "$TMPD/w.s" "$TMPD/w.pl" </dev/null 2>"$TMPD/err" || refuse "m4 compile failed: $(head -c 160 "$TMPD/err")"
        gcc -m64 -no-pie "$TMPD/w.s" -o "$TMPD/w.bin" -L"$RT" -lscrip_rt -Wl,-rpath,"$RT" -lm 2>"$TMPD/err" || refuse "m4 link failed: $(head -c 160 "$TMPD/err")"
        got="$(cd "$TMPD" && timeout -k 5 20 ./w.bin </dev/null 2>"$TMPD/err")"; rc=$?
        rm -f "$TMPD/w.s" "$TMPD/w.bin"
    fi
    if [ "$rc" = 0 ] && [ "$got" = "$want" ]; then echo "  ok  $mode"
    else echo "  RED $mode: rc=$rc out=[$(printf '%s' "$got" | tr '\n' '|' | cut -c1-200)] want [$(printf '%s' "$want" | tr '\n' '|')]"; red=$((red+1)); fi
done
[ "$red" = 0 ] || { echo "GATE FAIL [$GATE_NAME]: $red mode(s) red"; exit 1; }
echo "GATE PASS [$GATE_NAME]: big-integer multiplication is exact across the Karatsuba threshold, both modes as swipl"
exit 0
